return [{
  json: {
    q: '삼성전자',
    naver_display: 20,
    naver_sort: 'date',
    serper_gl: 'kr',
    serper_hl: 'ko',
    serper_num: 20,
    serper_tbs: 'qdr:d'
  }
}];

const naver = $('T2. HTTP Request - Naver News').first().json || {};
const serper = $('T3. HTTP Request - Serper News').first().json || {};

function stripHtml(v) {
  return String(v || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ').trim();
}
function normUrl(u) {
  return String(u || '')
    .replace(/#.*$/, '')
    .replace(/[?&](utm_[^=&]+|nclick)=[^&]*/gi, '')
    .replace(/[?&]$/, '')
    .replace(/\/$/, '');
}
function dateValue(v) {
  const d = new Date(v || 0);
  return isNaN(d.getTime()) ? Date.now() : d.getTime();
}
function toIso(v) {
  const d = new Date(v || 0);
  return isNaN(d.getTime()) ? new Date().toISOString() : d.toISOString();
}

// 주가/증시 시황 기사 하드 제외(제목 기준) — "투자·협력" 같은 사업 기사는 남기고,
// 단순 주가 등락/증시 코멘트류만 제외한다.
const STOCK_EXCLUDE = [
  '주가', '주식', '증시', '코스피', '코스닥', '목표주가', '투자의견', '매수의견', '매도의견',
  '상한가', '하한가', '52주', '시가총액', '순매수', '순매도', '개미', '반등', '폭락', '급락',
  '급등', '약세', '강세', '거래량', '신저가', '신고가'
];
function isStockNoise(title) {
  const t = String(title || '');
  return STOCK_EXCLUDE.some(term => t.includes(term));
}

// 뉴스레터 1단계 파이프라인의 "동일 사건 클러스터링" 로직과 동일한 방식(Jaccard 유사도)을
// 재사용해, 서로 다른 매체가 같은 사건을 다른 제목으로 보도해도 하나로 묶는다.
const STOP = new Set(['삼성전자', '삼성', '전자', '기자', '속보', '단독', '종합', '오늘', '이날', '관련', '대한', '이번']);
function tokens(v) {
  return String(v || '')
    .toLowerCase()
    .replace(/[^0-9a-z가-힣]/g, ' ')
    .split(/\s+/)
    .map(x => x.trim())
    .filter(x => x.length >= 2 && !STOP.has(x));
}
function tokenSet(v) { return new Set(tokens(v)); }
function jaccard(a, b) {
  const A = a instanceof Set ? a : tokenSet(a);
  const B = b instanceof Set ? b : tokenSet(b);
  if (!A.size || !B.size) return 0;
  let inter = 0;
  for (const x of A) if (B.has(x)) inter++;
  return inter / (A.size + B.size - inter);
}
function sameIssue(a, b) {
  const titleSim = jaccard(a.title, b.title);
  const allSim = jaccard(`${a.title} ${a.summary}`, `${b.title} ${b.summary}`);
  return titleSim >= 0.42 || allSim >= 0.34;
}

const naverArticles = (Array.isArray(naver.items) ? naver.items : []).map(r => ({
  title: stripHtml(r.title),
  url: String(r.originallink || r.link || '').trim(),
  source: 'Naver News',
  published_at_raw: r.pubDate || null,
  summary: stripHtml(r.description).slice(0, 300)
}));

const serperArticles = (Array.isArray(serper.news) ? serper.news : []).map(r => ({
  title: stripHtml(r.title),
  url: String(r.link || '').trim(),
  source: r.source || 'Serper News',
  published_at_raw: r.date || null,
  summary: stripHtml(r.snippet).slice(0, 300)
}));

const all = [...naverArticles, ...serperArticles]
  .filter(a => a.title && a.url)
  .filter(a => !isStockNoise(a.title));

// 1차: URL·제목 완전 중복 제거
const exactMap = new Map();
for (const a of all) {
  const key = normUrl(a.url) + '|' + tokens(a.title).join('');
  if (!exactMap.has(key)) exactMap.set(key, a);
}
const exactDeduped = [...exactMap.values()]
  .sort((a, b) => dateValue(b.published_at_raw) - dateValue(a.published_at_raw));

// 2차: 서로 다른 매체가 같은 사건을 보도한 경우 하나로 묶기(동일 사건 클러스터링)
const clusters = [];
for (const a of exactDeduped) {
  const cluster = clusters.find(c => sameIssue(c.representative, a));
  if (cluster) cluster.articles.push(a);
  else clusters.push({ representative: a, articles: [a] });
}

const deduped = clusters
  .slice(0, 5)
  .map(c => {
    const r = c.representative;
    return {
      title: r.title,
      url: r.url,
      source: c.articles.length > 1 ? `${r.source} 외 ${c.articles.length - 1}곳` : r.source,
      published_at: toIso(r.published_at_raw),
      summary: r.summary
    };
  });

if (!deduped.length) {
  throw new Error('삼성전자 관련 최근 기사를 하나도 찾지 못했습니다(주식 시황 기사 제외 후 0건). Naver/Serper 응답을 확인하세요.');
}

return [{ json: { articles: deduped } }];
